def _order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_packing_slip_unknown_order(shop):
    response = shop.fulfilment.handle_packing_slip("nope")
    assert response.status == 404
    assert response.body == {"error": "order not found"}


def test_packing_slip_cancelled_order(shop):
    order_id = _order(shop, "c1", ("BOOK", 1)).body["order_id"]
    shop.orders.handle_cancel(order_id)
    response = shop.fulfilment.handle_packing_slip(order_id)
    assert response.status == 409
    assert response.body["error"]


def test_packing_slip_lists_lines_in_order(shop):
    order_id = _order(shop, "c1", ("PEN", 3), ("BOOK", 1)).body["order_id"]
    response = shop.fulfilment.handle_packing_slip(order_id)
    assert response.status == 200
    assert response.body == {
        "order_id": order_id,
        "customer_name": "Ada",
        "lines": [{"sku": "PEN", "name": "Pen", "quantity": 3},
                  {"sku": "BOOK", "name": "Book", "quantity": 1}],
    }


def test_low_stock_filters_and_sorts(shop):
    shop.catalog.handle_add_product({"sku": "AAA", "name": "Apple", "unit_price_cents": 100, "on_hand": 5})
    shop.catalog.handle_add_product({"sku": "ZZZ", "name": "Zip", "unit_price_cents": 100, "on_hand": 0})
    response = shop.fulfilment.handle_low_stock(6)
    assert response.status == 200
    assert response.body == {"products": [
        {"sku": "ZZZ", "name": "Zip", "on_hand": 0},
        {"sku": "AAA", "name": "Apple", "on_hand": 5},
        {"sku": "LAMP", "name": "Lamp", "on_hand": 5},
    ]}


def test_low_stock_is_strictly_below_threshold(shop):
    assert shop.fulfilment.handle_low_stock(5).body == {"products": []}
    assert shop.fulfilment.handle_low_stock(0).body == {"products": []}


def test_low_stock_reflects_orders(shop):
    _order(shop, "c1", ("LAMP", 4))
    assert shop.fulfilment.handle_low_stock(2).body == {
        "products": [{"sku": "LAMP", "name": "Lamp", "on_hand": 1}]}


def test_restock_adds_to_stock(shop):
    response = shop.fulfilment.handle_restock({"sku": "LAMP", "quantity": 7})
    assert response.status == 200
    assert response.body == {"sku": "LAMP", "on_hand": 12}
    assert shop.fulfilment.handle_low_stock(13).body == {"products": [
        {"sku": "LAMP", "name": "Lamp", "on_hand": 12}]}


def test_restocked_units_are_orderable_immediately(shop):
    assert _order(shop, "c1", ("LAMP", 8)).status == 409
    shop.fulfilment.handle_restock({"sku": "LAMP", "quantity": 5})
    assert _order(shop, "c1", ("LAMP", 8)).status == 201
    assert shop.fulfilment.handle_restock({"sku": "LAMP", "quantity": 1}).body["on_hand"] == 3


def test_restock_unknown_product(shop):
    response = shop.fulfilment.handle_restock({"sku": "NOPE", "quantity": 1})
    assert response.status == 404
    assert response.body == {"error": "product not found"}


def test_restock_rejects_invalid_requests_without_change(shop):
    bad_requests = [{}, {"sku": "", "quantity": 1}, {"sku": 5, "quantity": 1}, {"sku": "LAMP"},
                    {"sku": "LAMP", "quantity": 0}, {"sku": "LAMP", "quantity": -2},
                    {"sku": "LAMP", "quantity": True}, {"sku": "LAMP", "quantity": 1.5},
                    {"sku": "LAMP", "quantity": "3"}]
    for bad in bad_requests:
        response = shop.fulfilment.handle_restock(bad)
        assert response.status == 400
        assert response.body["error"]
    assert shop.fulfilment.handle_low_stock(6).body == {"products": [
        {"sku": "LAMP", "name": "Lamp", "on_hand": 5}]}


def test_low_stock_rejects_invalid_threshold(shop):
    for bad in (-1, True, 1.5, "3", None):
        response = shop.fulfilment.handle_low_stock(bad)
        assert response.status == 400
        assert response.body["error"]
